// План specs/stripe-connect.md 1.1 (кейс .qa/tests/stripe-connect/SC-01). Pre-Prod (Stripe test mode), десктоп Chrome, EN.
// #06a307 Stripe Connect: у компании с завершённым Connect — «Active», текст компании, «Open Stripe dashboard» → Express dashboard.
// Только просмотр (данные не меняются). На prod (app.techory.ai) пропуск: там у TTP Test Locks Connect не Active.
// Не сверено с сайтом при записи (правило проекта — тесты только пишутся): роль бейджа «Active», открывается ли dashboard
// в новой вкладке (обработаны оба варианта). Разметка — по скриншоту 06a307-v2-step7-active-new-company-desktop.png.
import { test, expect } from '../../fixtures';
import { Page } from '@playwright/test';
import { COMPANY, IS_PROD, ROLE, pp } from '../job-payments/payments-helpers';

test.describe('Stripe Connect: Payment Settings (#06a307)', () => {
  test.skip(IS_PROD, 'на prod Connect у TTP Test Locks не Active — только Pre-Prod');

  test('Payment Settings shows Stripe Active for the company and Open Stripe dashboard leads to the Express dashboard #06a307 @desktop @stripe-test', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await page.goto(pp('/StripeSettings'));

    // Статус «Active» и тексты для активной компании (комментарий 11.10: статусы после возврата из Stripe)
    await expect(page.getByRole('heading', { name: 'Payment Settings' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('Card payments with Stripe', { exact: true })).toBeVisible();
    await expect(page.getByText('Active', { exact: true })).toBeVisible();
    await expect(page.getByText(`${COMPANY} can take card payments.`, { exact: true })).toBeVisible();
    await expect(page.getByText('Payouts to your bank account are on.', { exact: true })).toBeVisible();
    // Не показывается кнопка подключения / продолжения настройки
    await expect(page.getByRole('button', { name: /^(Connect Stripe|Continue setup)$/ })).toHaveCount(0);

    // «Open Stripe dashboard» → connect.stripe.com/app/express#acct_… (комментарий 11.10: баланс и выплаты)
    const button = page.getByRole('button', { name: 'Open Stripe dashboard' }).or(page.getByRole('link', { name: 'Open Stripe dashboard' })).first();
    await expect(button).toBeVisible();
    const target = await openDashboard(page, () => button.click());
    // Ссылка входа Stripe сначала может вести на connect.stripe.com/express/… — ждём итоговый адрес dashboard аккаунта компании
    await expect(target).toHaveURL(/^https:\/\/connect\.stripe\.com\/app\/express.*acct_\w+/, { timeout: 45_000 });
  });
});

/** Новая вкладка или переход в той же — возвращает страницу, где открылся Stripe. */
async function openDashboard(page: Page, click: () => Promise<void>): Promise<Page> {
  const target = Promise.any([
    page.context().waitForEvent('page', { timeout: 30_000 }),
    page.waitForURL(/connect\.stripe\.com/, { timeout: 30_000 }).then(() => page),
  ]);
  await click();
  return target;
}
